import { useState } from "react";
import { createUserAuthEmail, createUserDocumentFromAuth } from "../../utils/firebase/firebase.utils.js"
//import createUserAuthEmail from "../../utils/firebase/firebase.utils.js"


const defaultFormFields = {
    displayName: "",
    email: "",
    password: "",
    confirmPassword: ""
};



const SignUp = () => {
    const [formFields, setFormFields] = useState(defaultFormFields);
    const {displayName, email, password, confirmPassword} = formFields;


    const changeHandler = (event) => {
        const whichFieldToPick = event.target.name;
        const setThisValue = event.target.value;
        setFormFields( {...formFields, [whichFieldToPick]: setThisValue } );
        
    };


    const resetFormFields = () => {
        setFormFields( defaultFormFields );
    };


    const submitHandler = async (event) => {
        event.preventDefault();

        if (password !== confirmPassword) {
            alert("Passwords do not match");
            return;
        };

        try {
            const { user } = await createUserAuthEmail(email, password);
            await createUserDocumentFromAuth(user, {displayName});
            console.log(user);
            resetFormFields();

        }catch(error){
            console.log(error);
            if(error.code === ``)

            console.log("User creation encountered an error\n",error);
        };

    };


    console.log(formFields);

    return(
        <div>
            <h1>Sign up with your email and password</h1>
            <form onSubmit={ submitHandler } >
                <label>Display Name</label>
                <input type="text" onChange={changeHandler} name="displayName" value={displayName} required/>

                <label>Email</label>
                <input type="email" onChange={changeHandler} name="email" value={email} required/>

                <label>Password</label>
                <input type="password" onChange={changeHandler} name="password" value={password} required/>

                <label>Confirm Password</label>
                <input type="password" onChange={changeHandler} name="confirmPassword" value={confirmPassword} required/>

                <button type="submit">Sign Up</button>
            </form>
        </div>
    );
};

export default SignUp;
